(587, 'Đồng hồ Thông minh', NULL, '<h3>Đồng hành cùng sức khỏe và sự tiện lợi</h3>\n<p>Apple Watch Series 9 mang đến khả năng tương tác kỳ diệu nhờ tính năng Chạm Hai Lần (Double Tap).</p>\n<ul>\n    <li><strong>Chip:</strong> S9 SiP mới nhất, xử lý nhanh và mượt mà.</li>\n    <li><strong>Độ sáng màn hình:</strong> Lên đến 2000 nits, hiển thị tốt dưới trời nắng gắt.</li>\n    <li><strong>Sức khỏe:</strong> Theo dõi nồng độ Oxy trong máu, điện tâm đồ (ECG) và giấc ngủ.</li>\n</ul>\n<p><i>Sản phẩm thân thiện với môi trường với vật liệu tái chế 100%.</i></p>', NULL, 14, 2, 10490000.00, 1, 0, NULL, NULL, '2026-03-12 03:41:53', '2026-03-12 03:41:53'),
(588, 'Sản phẩm Nổi Bật Đặc Biệt (Test) - 7827', NULL, 'Sản phẩm này đặc biệt dùng để kiểm thử cờ Nổi Bật của hệ thống.', NULL, 1, 1, 12000000.00, 0, 1, NULL, NULL, '2026-03-18 11:07:53', '2026-03-21 07:04:35'),
(589, 'techguru123', NULL, 'sản phẩm chất lươgj', NULL, 12, 6, 275695855.00, 1, 0, NULL, NULL, '2026-04-25 12:51:32', '2026-04-25 12:51:32');
